use split_decls_genesis :: ourprelude :: * ; use crate :: num :: NonZero ; use crate :: ops :: { ControlFlow , Try } ; #[doc = " An iterator able to yield elements from both ends."] #[doc = ""] #[doc = " Something that implements `DoubleEndedIterator` has one extra capability"] #[doc = " over something that implements [`Iterator`]: the ability to also take"] #[doc = " `Item`s from the back, as well as the front."] #[doc = ""] #[doc = " It is important to note that both back and forth work on the same range,"] #[doc = " and do not cross: iteration is over when they meet in the middle."] #[doc = ""] #[doc = " In a similar fashion to the [`Iterator`] protocol, once a"] #[doc = " `DoubleEndedIterator` returns [`None`] from a [`next_back()`], calling it"] #[doc = " again may or may not ever return [`Some`] again. [`next()`] and"] #[doc = " [`next_back()`] are interchangeable for this purpose."] #[doc = ""] #[doc = " [`next_back()`]: DoubleEndedIterator::next_back"] #[doc = " [`next()`]: Iterator::next"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " let numbers = vec![1, 2, 3, 4, 5, 6];"] #[doc = ""] #[doc = " let mut iter = numbers.iter();"] #[doc = ""] #[doc = " assert_eq!(Some(&1), iter.next());"] #[doc = " assert_eq!(Some(&6), iter.next_back());"] #[doc = " assert_eq!(Some(&5), iter.next_back());"] #[doc = " assert_eq!(Some(&2), iter.next());"] #[doc = " assert_eq!(Some(&3), iter.next());"] #[doc = " assert_eq!(Some(&4), iter.next());"] #[doc = " assert_eq!(None, iter.next());"] #[doc = " assert_eq!(None, iter.next_back());"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] #[rustc_diagnostic_item = "DoubleEndedIterator"] pub trait DoubleEndedIterator : Iterator { #[doc = " Removes and returns an element from the end of the iterator."] #[doc = ""] #[doc = " Returns `None` when there are no more elements."] #[doc = ""] #[doc = " The [trait-level] docs contain more details."] #[doc = ""] #[doc = " [trait-level]: DoubleEndedIterator"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " let numbers = vec![1, 2, 3, 4, 5, 6];"] #[doc = ""] #[doc = " let mut iter = numbers.iter();"] #[doc = ""] #[doc = " assert_eq!(Some(&1), iter.next());"] #[doc = " assert_eq!(Some(&6), iter.next_back());"] #[doc = " assert_eq!(Some(&5), iter.next_back());"] #[doc = " assert_eq!(Some(&2), iter.next());"] #[doc = " assert_eq!(Some(&3), iter.next());"] #[doc = " assert_eq!(Some(&4), iter.next());"] #[doc = " assert_eq!(None, iter.next());"] #[doc = " assert_eq!(None, iter.next_back());"] #[doc = " ```"] #[doc = ""] #[doc = " # Remarks"] #[doc = ""] #[doc = " The elements yielded by `DoubleEndedIterator`'s methods may differ from"] #[doc = " the ones yielded by [`Iterator`]'s methods:"] #[doc = ""] #[doc = " ```"] #[doc = " let vec = vec![(1, 'a'), (1, 'b'), (1, 'c'), (2, 'a'), (2, 'b')];"] #[doc = " let uniq_by_fst_comp = || {"] #[doc = "     let mut seen = std::collections::HashSet::new();"] #[doc = "     vec.iter().copied().filter(move |x| seen.insert(x.0))"] #[doc = " };"] #[doc = ""] #[doc = " assert_eq!(uniq_by_fst_comp().last(), Some((2, 'a')));"] #[doc = " assert_eq!(uniq_by_fst_comp().next_back(), Some((2, 'b')));"] #[doc = ""] #[doc = " assert_eq!("] #[doc = "     uniq_by_fst_comp().fold(vec![], |mut v, x| {v.push(x); v}),"] #[doc = "     vec![(1, 'a'), (2, 'a')]"] #[doc = " );"] #[doc = " assert_eq!("] #[doc = "     uniq_by_fst_comp().rfold(vec![], |mut v, x| {v.push(x); v}),"] #[doc = "     vec![(2, 'b'), (1, 'c')]"] #[doc = " );"] #[doc = " ```"] #[stable (feature = "rust1" , since = "1.0.0")] fn next_back (& mut self) -> Option < Self :: Item > ; #[doc = " Advances the iterator from the back by `n` elements."] #[doc = ""] #[doc = " `advance_back_by` is the reverse version of [`advance_by`]. This method will"] #[doc = " eagerly skip `n` elements starting from the back by calling [`next_back`] up"] #[doc = " to `n` times until [`None`] is encountered."] #[doc = ""] #[doc = " `advance_back_by(n)` will return `Ok(())` if the iterator successfully advances by"] #[doc = " `n` elements, or a `Err(NonZero<usize>)` with value `k` if [`None`] is encountered, where `k`"] #[doc = " is remaining number of steps that could not be advanced because the iterator ran out."] #[doc = " If `self` is empty and `n` is non-zero, then this returns `Err(n)`."] #[doc = " Otherwise, `k` is always less than `n`."] #[doc = ""] #[doc = " Calling `advance_back_by(0)` can do meaningful work, for example [`Flatten`] can advance its"] #[doc = " outer iterator until it finds an inner iterator that is not empty, which then often"] #[doc = " allows it to return a more accurate `size_hint()` than in its initial state."] #[doc = ""] #[doc = " [`advance_by`]: Iterator::advance_by"] #[doc = " [`Flatten`]: crate::iter::Flatten"] #[doc = " [`next_back`]: DoubleEndedIterator::next_back"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " #![feature(iter_advance_by)]"] #[doc = ""] #[doc = " use std::num::NonZero;"] #[doc = ""] #[doc = " let a = [3, 4, 5, 6];"] #[doc = " let mut iter = a.iter();"] #[doc = ""] #[doc = " assert_eq!(iter.advance_back_by(2), Ok(()));"] #[doc = " assert_eq!(iter.next_back(), Some(&4));"] #[doc = " assert_eq!(iter.advance_back_by(0), Ok(()));"] #[doc = " assert_eq!(iter.advance_back_by(100), Err(NonZero::new(99).unwrap())); // only `&3` was skipped"] #[doc = " ```"] #[doc = ""] #[doc = " [`Ok(())`]: Ok"] #[doc = " [`Err(k)`]: Err"] #[inline] #[unstable (feature = "iter_advance_by" , reason = "recently added" , issue = "77404")] fn advance_back_by (& mut self , n : usize) -> Result < () , NonZero < usize > > { for i in 0 .. n { if self . next_back () . is_none () { return Err (unsafe { NonZero :: new_unchecked (n - i) }) ; } } Ok (()) } #[doc = " Returns the `n`th element from the end of the iterator."] #[doc = ""] #[doc = " This is essentially the reversed version of [`Iterator::nth()`]."] #[doc = " Although like most indexing operations, the count starts from zero, so"] #[doc = " `nth_back(0)` returns the first value from the end, `nth_back(1)` the"] #[doc = " second, and so on."] #[doc = ""] #[doc = " Note that all elements between the end and the returned element will be"] #[doc = " consumed, including the returned element. This also means that calling"] #[doc = " `nth_back(0)` multiple times on the same iterator will return different"] #[doc = " elements."] #[doc = ""] #[doc = " `nth_back()` will return [`None`] if `n` is greater than or equal to the"] #[doc = " length of the iterator."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " let a = [1, 2, 3];"] #[doc = " assert_eq!(a.iter().nth_back(2), Some(&1));"] #[doc = " ```"] #[doc = ""] #[doc = " Calling `nth_back()` multiple times doesn't rewind the iterator:"] #[doc = ""] #[doc = " ```"] #[doc = " let a = [1, 2, 3];"] #[doc = ""] #[doc = " let mut iter = a.iter();"] #[doc = ""] #[doc = " assert_eq!(iter.nth_back(1), Some(&2));"] #[doc = " assert_eq!(iter.nth_back(1), None);"] #[doc = " ```"] #[doc = ""] #[doc = " Returning `None` if there are less than `n + 1` elements:"] #[doc = ""] #[doc = " ```"] #[doc = " let a = [1, 2, 3];"] #[doc = " assert_eq!(a.iter().nth_back(10), None);"] #[doc = " ```"] #[inline] #[stable (feature = "iter_nth_back" , since = "1.37.0")] fn nth_back (& mut self , n : usize) -> Option < Self :: Item > { if self . advance_back_by (n) . is_err () { return None ; } self . next_back () } #[doc = " This is the reverse version of [`Iterator::try_fold()`]: it takes"] #[doc = " elements starting from the back of the iterator."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " let a = [\"1\", \"2\", \"3\"];"] #[doc = " let sum = a.iter()"] #[doc = "     .map(|&s| s.parse::<i32>())"] #[doc = "     .try_rfold(0, |acc, x| x.and_then(|y| Ok(acc + y)));"] #[doc = " assert_eq!(sum, Ok(6));"] #[doc = " ```"] #[doc = ""] #[doc = " Short-circuiting:"] #[doc = ""] #[doc = " ```"] #[doc = " let a = [\"1\", \"rust\", \"3\"];"] #[doc = " let mut it = a.iter();"] #[doc = " let sum = it"] #[doc = "     .by_ref()"] #[doc = "     .map(|&s| s.parse::<i32>())"] #[doc = "     .try_rfold(0, |acc, x| x.and_then(|y| Ok(acc + y)));"] #[doc = " assert!(sum.is_err());"] #[doc = ""] #[doc = " // Because it short-circuited, the remaining elements are still"] #[doc = " // available through the iterator."] #[doc = " assert_eq!(it.next_back(), Some(&\"1\"));"] #[doc = " ```"] #[inline] #[stable (feature = "iterator_try_fold" , since = "1.27.0")] fn try_rfold < B , F , R > (& mut self , init : B , mut f : F) -> R where Self : Sized , F : FnMut (B , Self :: Item) -> R , R : Try < Output = B > , { let mut accum = init ; while let Some (x) = self . next_back () { accum = f (accum , x) ? ; } try { accum } } #[doc = " An iterator method that reduces the iterator's elements to a single,"] #[doc = " final value, starting from the back."] #[doc = ""] #[doc = " This is the reverse version of [`Iterator::fold()`]: it takes elements"] #[doc = " starting from the back of the iterator."] #[doc = ""] #[doc = " `rfold()` takes two arguments: an initial value, and a closure with two"] #[doc = " arguments: an 'accumulator', and an element. The closure returns the value that"] #[doc = " the accumulator should have for the next iteration."] #[doc = ""] #[doc = " The initial value is the value the accumulator will have on the first"] #[doc = " call."] #[doc = ""] #[doc = " After applying this closure to every element of the iterator, `rfold()`"] #[doc = " returns the accumulator."] #[doc = ""] #[doc = " This operation is sometimes called 'reduce' or 'inject'."] #[doc = ""] #[doc = " Folding is useful whenever you have a collection of something, and want"] #[doc = " to produce a single value from it."] #[doc = ""] #[doc = " Note: `rfold()` combines elements in a *right-associative* fashion. For associative"] #[doc = " operators like `+`, the order the elements are combined in is not important, but for non-associative"] #[doc = " operators like `-` the order will affect the final result."] #[doc = " For a *left-associative* version of `rfold()`, see [`Iterator::fold()`]."] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " let a = [1, 2, 3];"] #[doc = ""] #[doc = " // the sum of all of the elements of a"] #[doc = " let sum = a.iter()"] #[doc = "            .rfold(0, |acc, &x| acc + x);"] #[doc = ""] #[doc = " assert_eq!(sum, 6);"] #[doc = " ```"] #[doc = ""] #[doc = " This example demonstrates the right-associative nature of `rfold()`:"] #[doc = " it builds a string, starting with an initial value"] #[doc = " and continuing with each element from the back until the front:"] #[doc = ""] #[doc = " ```"] #[doc = " let numbers = [1, 2, 3, 4, 5];"] #[doc = ""] #[doc = " let zero = \"0\".to_string();"] #[doc = ""] #[doc = " let result = numbers.iter().rfold(zero, |acc, &x| {"] #[doc = "     format!(\"({x} + {acc})\")"] #[doc = " });"] #[doc = ""] #[doc = " assert_eq!(result, \"(1 + (2 + (3 + (4 + (5 + 0)))))\");"] #[doc = " ```"] #[doc (alias = "foldr")] #[inline] #[stable (feature = "iter_rfold" , since = "1.27.0")] fn rfold < B , F > (mut self , init : B , mut f : F) -> B where Self : Sized , F : FnMut (B , Self :: Item) -> B , { let mut accum = init ; while let Some (x) = self . next_back () { accum = f (accum , x) ; } accum } #[doc = " Searches for an element of an iterator from the back that satisfies a predicate."] #[doc = ""] #[doc = " `rfind()` takes a closure that returns `true` or `false`. It applies"] #[doc = " this closure to each element of the iterator, starting at the end, and if any"] #[doc = " of them return `true`, then `rfind()` returns [`Some(element)`]. If they all return"] #[doc = " `false`, it returns [`None`]."] #[doc = ""] #[doc = " `rfind()` is short-circuiting; in other words, it will stop processing"] #[doc = " as soon as the closure returns `true`."] #[doc = ""] #[doc = " Because `rfind()` takes a reference, and many iterators iterate over"] #[doc = " references, this leads to a possibly confusing situation where the"] #[doc = " argument is a double reference. You can see this effect in the"] #[doc = " examples below, with `&&x`."] #[doc = ""] #[doc = " [`Some(element)`]: Some"] #[doc = ""] #[doc = " # Examples"] #[doc = ""] #[doc = " Basic usage:"] #[doc = ""] #[doc = " ```"] #[doc = " let a = [1, 2, 3];"] #[doc = ""] #[doc = " assert_eq!(a.iter().rfind(|&&x| x == 2), Some(&2));"] #[doc = ""] #[doc = " assert_eq!(a.iter().rfind(|&&x| x == 5), None);"] #[doc = " ```"] #[doc = ""] #[doc = " Stopping at the first `true`:"] #[doc = ""] #[doc = " ```"] #[doc = " let a = [1, 2, 3];"] #[doc = ""] #[doc = " let mut iter = a.iter();"] #[doc = ""] #[doc = " assert_eq!(iter.rfind(|&&x| x == 2), Some(&2));"] #[doc = ""] #[doc = " // we can still use `iter`, as there are more elements."] #[doc = " assert_eq!(iter.next_back(), Some(&1));"] #[doc = " ```"] #[inline] #[stable (feature = "iter_rfind" , since = "1.27.0")] fn rfind < P > (& mut self , predicate : P) -> Option < Self :: Item > where Self : Sized , P : FnMut (& Self :: Item) -> bool , { #[inline] fn check < T > (mut predicate : impl FnMut (& T) -> bool) -> impl FnMut (() , T) -> ControlFlow < T > { move | () , x | { if predicate (& x) { ControlFlow :: Break (x) } else { ControlFlow :: Continue (()) } } } self . try_rfold (() , check (predicate)) . break_value () } } #[stable (feature = "rust1" , since = "1.0.0")] impl < 'a , I : DoubleEndedIterator + ? Sized > DoubleEndedIterator for & 'a mut I { fn next_back (& mut self) -> Option < I :: Item > { (* * self) . next_back () } fn advance_back_by (& mut self , n : usize) -> Result < () , NonZero < usize > > { (* * self) . advance_back_by (n) } fn nth_back (& mut self , n : usize) -> Option < I :: Item > { (* * self) . nth_back (n) } fn rfold < B , F > (self , init : B , f : F) -> B where F : FnMut (B , Self :: Item) -> B , { self . spec_rfold (init , f) } fn try_rfold < B , F , R > (& mut self , init : B , f : F) -> R where F : FnMut (B , Self :: Item) -> R , R : Try < Output = B > , { self . spec_try_rfold (init , f) } } #[doc = " Helper trait to specialize `rfold` and `rtry_fold` for `&mut I where I: Sized`"] trait DoubleEndedIteratorRefSpec : DoubleEndedIterator { fn spec_rfold < B , F > (self , init : B , f : F) -> B where F : FnMut (B , Self :: Item) -> B ; fn spec_try_rfold < B , F , R > (& mut self , init : B , f : F) -> R where F : FnMut (B , Self :: Item) -> R , R : Try < Output = B > ; } impl < I : DoubleEndedIterator + ? Sized > DoubleEndedIteratorRefSpec for & mut I { default fn spec_rfold < B , F > (self , init : B , mut f : F) -> B where F : FnMut (B , Self :: Item) -> B , { let mut accum = init ; while let Some (x) = self . next_back () { accum = f (accum , x) ; } accum } default fn spec_try_rfold < B , F , R > (& mut self , init : B , mut f : F) -> R where F : FnMut (B , Self :: Item) -> R , R : Try < Output = B > , { let mut accum = init ; while let Some (x) = self . next_back () { accum = f (accum , x) ? ; } try { accum } } } impl < I : DoubleEndedIterator > DoubleEndedIteratorRefSpec for & mut I { impl_fold_via_try_fold ! { spec_rfold -> spec_try_rfold } fn spec_try_rfold < B , F , R > (& mut self , init : B , f : F) -> R where F : FnMut (B , Self :: Item) -> R , R : Try < Output = B > , { (* * self) . try_rfold (init , f) } }